/* Trubond service worker.
 *
 * Hand-written rather than generated by a plugin: adding a build-touching
 * dependency to a statically exported Next app is a lot of risk for a cache
 * policy this small.
 *
 * Strategy
 *   - /_next/static/** and /favicon/** are content-hashed or immutable, so
 *     cache-first is safe and makes repeat visits instant.
 *   - Navigations are network-first so a deploy is picked up immediately, with
 *     a cached copy and then /offline.html as fallbacks.
 *   - Everything cross-origin (Firestore, Cloudinary, Google auth) is left
 *     completely alone — caching API traffic causes very confusing bugs.
 */

const VERSION = "trubond-v1";
const STATIC_CACHE = `${VERSION}-static`;

self.addEventListener("install", () => {
  // Take over as soon as possible rather than waiting for every tab to close.
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys.filter((key) => !key.startsWith(VERSION)).map((key) => caches.delete(key))
      );
      await self.clients.claim();
    })()
  );
});

self.addEventListener("fetch", (event) => {
  const { request } = event;

  // Only GET is cacheable.
  if (request.method !== "GET") return;

  const url = new URL(request.url);

  // Never touch another origin's traffic.
  if (url.origin !== self.location.origin) return;

  // Next.js serves these from /_next/static with a content hash in the name.
  if (
    url.pathname.startsWith("/_next/static/") ||
    url.pathname.startsWith("/favicon/")
  ) {
    event.respondWith(
      (async () => {
        const cached = await caches.match(request);
        if (cached) return cached;
        const response = await fetch(request);
        if (response.ok) {
          const cache = await caches.open(STATIC_CACHE);
          cache.put(request, response.clone());
        }
        return response;
      })()
    );
    return;
  }

  if (request.mode === "navigate") {
    event.respondWith(
      (async () => {
        try {
          const response = await fetch(request);
          if (response.ok) {
            const cache = await caches.open(STATIC_CACHE);
            cache.put(request, response.clone());
          }
          return response;
        } catch {
          const cached = await caches.match(request);
          if (cached) return cached;
          const offline = await caches.match("/offline.html");
          return offline || Response.error();
        }
      })()
    );
  }
});
